set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
select test_assert(private.can_upload_driver_earnings('00000000-0000-0000-0000-000000000001/20000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000001/40000000-0000-0000-0000-000000000001.pdf'),'admin may stage own company PDF');
select test_assert(not private.can_upload_driver_earnings('00000000-0000-0000-0000-000000000001/30000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000001/40000000-0000-0000-0000-000000000001.pdf'),'cross tenant upload denied');
select test_error($s$select public.publish_driver_earnings('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2026-10-12','2026-10-18',850000,721250,2,'statement.pdf',repeat('a',64),100)$s$,'cannot publish missing PDF');
insert into storage.objects(bucket_id,name,owner_id,metadata) values('driver-earnings','00000000-0000-0000-0000-000000000001/20000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000001/40000000-0000-0000-0000-000000000001.pdf','10000000-0000-0000-0000-000000000001','{"size":100,"mimetype":"application/pdf"}');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);
select test_assert((select count(*)=0 from storage.objects),'unpublished PDF invisible to driver');
select test_error($s$select public.publish_driver_earnings('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2026-10-12','2026-10-18',850000,721250,2,'statement.pdf',repeat('a',64),100)$s$,'driver cannot publish');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
select test_assert((public.publish_driver_earnings('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2026-10-12','2026-10-18',850000,721250,2,'statement.pdf',repeat('a',64),100)).net_cents=721250,'publish exact Net');
select public.publish_driver_earnings('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2026-10-12','2026-10-18',850000,721250,2,'statement.pdf',repeat('a',64),100);
select test_assert((select count(*)=1 from driver_earnings),'retry creates only one statement');
select test_error($s$select public.publish_driver_earnings('40000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2026-10-12','2026-10-18',850000,0,2,'statement.pdf',repeat('a',64),100)$s$,'same ID cannot change amounts');
select test_error($s$update driver_earnings set net_cents=0$s$,'published metadata immutable');
select test_assert(not private.can_upload_driver_earnings('00000000-0000-0000-0000-000000000001/20000000-0000-0000-0000-000000000001/10000000-0000-0000-0000-000000000001/40000000-0000-0000-0000-000000000001.pdf'),'published PDF cannot be replaced');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);
select test_assert((select count(*)=1 from driver_earnings),'recipient reads earnings');
select test_assert((select count(*)=1 from storage.objects),'recipient reads exact PDF');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',false);
select test_assert((select count(*)=0 from driver_earnings),'other driver cannot read earnings');
select test_assert((select count(*)=0 from storage.objects),'other driver cannot read PDF');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',false);
select test_assert((select count(*)=0 from driver_earnings),'dispatcher cannot read private earnings');
select test_assert((select count(*)=0 from storage.objects),'dispatcher cannot read private PDF');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',false);
select test_assert((select count(*)=0 from driver_earnings),'cross company rows invisible');
select test_assert((select count(*)=0 from storage.objects),'cross company PDFs invisible');
reset role;
select test_assert((select count(*)=1 from audit_events),'one immutable send audit');
